export type RouteIntent = keyof typeof ROUTE_INTENTS;

export const ROUTE_INTENT_IDS = Object.keys(ROUTE_INTENTS) as RouteIntent[];

export function parseRouteIntent(value: unknown): RouteIntent | null {
  return typeof value === 'string' && value in ROUTE_INTENTS ? (value as RouteIntent) : null;
}

