/**
 * Where a class lands in OrchestKit. `skill` entries are invoked through the
 * Skill tool as `/ork:<skill>`; the `Explore` entry is an agent. `null` means
 * no ork nudge: the ops classes are the hq-ext front door's business, and
 * `continuation` and `ambiguous` are never steered.
 */
export interface RouteTarget {
  kind: 'skill' | 'agent';
  name: string;
}

const skill = (name: string): RouteTarget => ({ kind: 'skill', name });

export const ROUTE_CLASS_TO_EXECUTOR: Record<RouteIntent, RouteTarget | null> = {
  dev_fix: skill('fix-issue'),
  dev_build: skill('implement'),
  dev_review: skill('review-pr'),
  dev_verify: skill('verify'),
  dev_design: skill('brainstorm'),
  ops_brief: null,
  ops_comms: null,
  ops_client: null,
  ops_deploy: null,
  ops_content: null,
  ops_commerce: null,
  ops_observability: null,
  ops_deps: null,
  ops_security_infra: null,
  research: { kind: 'agent', name: 'Explore' },
  visual: skill('glyph'),
  session_admin: skill('remember'),
  continuation: null,
  ambiguous: null,
};

/** The one line a steer nudge carries, e.g. `route: dev_fix -> /ork:fix-issue (conf 0.83)`. */
export function formatRouteTarget(target: RouteTarget): string {
  return target.kind === 'skill' ? `/ork:${target.name}` : `Agent(${target.name})`;
}

